using System;
using System.Collections.Generic;
using System.Linq;
using LastRail.Run;
using Newtonsoft.Json.Linq;
namespace LastRail.Battle {
 internal sealed class BEnemyBoardingOwner:IBWaveEnemyPerception,IBWaveSpatialPerception {
  sealed class Life {internal string Id;internal int Ordinal,Slot=-1,Socket=-1;internal long Generation,Entered,PhaseStarted,Due,ApproachCompleted;internal bool Registered,RoofScheduled;internal BEnemyBoardingPhase Phase=BEnemyBoardingPhase.Planned;internal Life Copy()=>(Life)MemberwiseClone();}
  internal BOrdinarySpatialOwner Spatial;public bool HasSpatial=>Spatial!=null;public string SpatialTarget(string id)=>Spatial?.Target(id);public bool TryGeometry(string source,string target,long tick,out JObject frame){frame=null;return Spatial?.TryGeometry(source,target,tick,out frame)??false;}public bool Protection(string actor,string target)=>Spatial?.Protection(actor,target)??false;
  readonly BBoardingRoster input;readonly BWaveBoardingPolicy policy;readonly BWaveBoardingLocalPaths paths;readonly long step;readonly List<Life> lives=new List<Life>();readonly JArray events=new JArray();
  internal BEnemyBoardingOwner(BScoutGunnerNodeSnapshot source,BDirectAttackInput input,BWaveBoardingPolicy policy,BWaveBoardingLocalPaths paths):this(source,BBoardingRoster.FromNative(input),policy,paths){}
  internal BEnemyBoardingOwner(BScoutGunnerNodeSnapshot source,BBoardingRoster input,BWaveBoardingPolicy policy,BWaveBoardingLocalPaths paths){this.input=input;this.policy=policy;this.paths=paths;step=input.StepMicroseconds;int ordinal=0;foreach(var x in source.Waves.SelectMany(w=>w.Instances))lives.Add(new Life{Id=x.InstanceId,Ordinal=ordinal++});}
  BEnemyBoardingOwner(BEnemyBoardingOwner value){Spatial=value.Spatial?.Clone();input=value.input;policy=value.policy;paths=value.paths;step=value.step;lives.AddRange(value.lives.Select(x=>x.Copy()));foreach(var e in value.events)events.Add(e.DeepClone());}
  internal BEnemyBoardingOwner Clone()=>new BEnemyBoardingOwner(this);
  Life Find(string id)=>lives.Single(x=>x.Id==id);
  internal int Alive=>lives.Count(x=>x.Registered);
  internal bool Registered(string id)=>Find(id).Registered;
  internal long Generation(string id)=>Find(id).Generation;
  public bool Targetable(string id){var x=Find(id);return x.Registered&&policy.PhaseTargetable(x.Phase);}
  bool BoundGeometry(Life x)=>paths!=null&&paths.HasRoute(x.Slot)&&(Spatial!=null||input.Entities[x.Id].Slot==x.Slot);
  string GeometryStatus(Life x)=>Spatial!=null?"TEST_JUDGEMENT_MODEL_REAL_NATIVE_SPATIAL_SOURCE":paths==null||!paths.HasRoute(x.Slot)?"APPROACH_CLIMB_SOCKET_SOURCE_MISSING":input.Entities[x.Id].Slot!=x.Slot?"ASSIGNED_SLOT_OBSERVATION_MISSING":"EXPLICIT_LOCAL_GRAPH_FIXTURE";
  public bool AttackEligible(string id){var x=Find(id);return x.Registered&&policy.PhaseAttackEligible(x.Phase)&&BoundGeometry(x)&&(Spatial==null||Spatial.Ready(id));}
  public int Slot(string id)=>Spatial?.Slot(id)>=0?Spatial.Slot(id):Find(id).Slot;
  public string CategoryAtImpact(string id){var phase=Find(id).Phase;if(policy.ClimbingBonusAtImpact(phase))return phase==BEnemyBoardingPhase.Attached?"ATTACHED":"CLIMBING";return phase==BEnemyBoardingPhase.Rooftop?"ROOFTOP":"APPROACH";}
  internal bool AllDead(IEnumerable<string> ids)=>ids.All(id=>Find(id).Phase==BEnemyBoardingPhase.Dead);
  internal IEnumerable<string> TargetableOrder()=>lives.Where(x=>Targetable(x.Id)).OrderBy(x=>x.Ordinal).Select(x=>x.Id);
  IEnumerable<int> LivingOperatorSlots(IBBoardingActors native)=>input.Entities.Values.Where(e=>e.Kind=="OPERATOR"&&native.Hp(e.Id)>0).Select(e=>Spatial?.Slot(e.Id)??e.Slot).Distinct();
  internal int Destination(IBBoardingActors native){return LivingOperatorSlots(native).OrderBy(slot=>lives.Count(x=>x.Registered&&x.Slot==slot&&x.Phase!=BEnemyBoardingPhase.Rooftop)).ThenBy(slot=>slot).DefaultIfEmpty(-1).First();}
  void Event(Life x,string kind,long tick,Func<long> sequence){events.Add(new JObject{["instanceId"]=x.Id,["generation"]=x.Generation,["tick"]=tick,["sequence"]=sequence(),["kind"]=kind,["phase"]=x.Phase.ToString(),["slot"]=x.Slot,["socketId"]=x.Socket<0?JValue.CreateNull():new JValue(paths.Socket(x.Slot,x.Socket))});}
  internal bool Enter(string id,IBBoardingActors native,Func<long> sequence){var x=Find(id);BuffWire.Need(!x.Registered&&x.Generation==0&&x.Phase==BEnemyBoardingPhase.Planned,"b_wave_duplicate_registration");int slot=Destination(native);if(slot<0)return false;x.Registered=true;x.Generation=1;x.Slot=slot;x.Entered=x.PhaseStarted=native.Tick;x.Due=checked(native.Tick+policy.DurationTicks(policy.EntranceMilliseconds,step));x.Phase=BEnemyBoardingPhase.Entrance;Event(x,"REGISTER",native.Tick,sequence);Spatial?.Observe(x.Id,x.Slot,x.Ordinal%2,x.Phase.ToString(),x.PhaseStarted,x.Generation,native);return true;}
  internal void ObserveDeaths(IBBoardingActors native,Func<long> sequence){foreach(var x in lives.Where(x=>x.Registered&&native.Hp(x.Id)==0).OrderBy(x=>x.Ordinal)){if(x.Socket>=0){Event(x,"SOCKET_RETURN_DEATH",native.Tick,sequence);x.Socket=-1;}x.Registered=false;x.Generation++;x.Phase=BEnemyBoardingPhase.Dead;x.Due=0;Event(x,"UNREGISTER_DEATH",native.Tick,sequence);}}
  void Transition(Life x,BEnemyBoardingPhase phase,long tick,int milliseconds,Func<long> sequence){x.Phase=phase;x.PhaseStarted=tick;x.Due=milliseconds==0?0:checked(tick+(Spatial!=null&&(phase==BEnemyBoardingPhase.Approach||phase==BEnemyBoardingPhase.Climbing)?Spatial.PhaseTicks(x.Id,x.Slot,x.Socket<0?x.Ordinal%2:x.Socket,phase.ToString(),policy.DurationTicks(milliseconds,step)):policy.DurationTicks(milliseconds,step)));Event(x,"PHASE",tick,sequence);}
  internal void Step(IBBoardingActors native,Func<long> sequence){Spatial?.ObserveOperators(native);ObserveDeaths(native,sequence);foreach(var x in lives.Where(x=>x.Registered).OrderBy(x=>x.Ordinal)){if(x.Phase==BEnemyBoardingPhase.GeometryPending&&Spatial!=null){int destination=LivingOperatorSlots(native).Where(slot=>Spatial.Connected(x.Slot,slot)).OrderBy(slot=>Math.Abs(slot-x.Slot)).ThenBy(slot=>slot).DefaultIfEmpty(-1).First();if(Spatial.Repath(x.Id,x.Ordinal%2,destination,native)){x.Slot=destination;Transition(x,BEnemyBoardingPhase.Approach,native.Tick,policy.ApproachMilliseconds,sequence);}continue;}if(!LivingOperatorSlots(native).Contains(x.Slot)&&(x.Phase==BEnemyBoardingPhase.Approach||x.Phase==BEnemyBoardingPhase.WaitingSocket)){Transition(x,BEnemyBoardingPhase.GeometryPending,native.Tick,0,sequence);continue;}if(x.Phase==BEnemyBoardingPhase.Entrance&&native.Tick>=x.Due){if(!BoundGeometry(x)||!LivingOperatorSlots(native).Contains(x.Slot))Transition(x,BEnemyBoardingPhase.GeometryPending,native.Tick,0,sequence);else Transition(x,BEnemyBoardingPhase.Approach,native.Tick,policy.ApproachMilliseconds,sequence);}else if(x.Phase==BEnemyBoardingPhase.Approach&&native.Tick>=x.Due){x.ApproachCompleted=native.Tick;Transition(x,BEnemyBoardingPhase.WaitingSocket,native.Tick,0,sequence);}else if(x.Phase==BEnemyBoardingPhase.Attached&&native.Tick>=x.Due)Transition(x,BEnemyBoardingPhase.Climbing,native.Tick,policy.ClimbingMilliseconds,sequence);else if(x.Phase==BEnemyBoardingPhase.Climbing&&native.Tick>=x.Due){Event(x,"SOCKET_RETURN_ROOF",native.Tick,sequence);x.Socket=-1;Transition(x,BEnemyBoardingPhase.Rooftop,native.Tick,0,sequence);}}
   foreach(var x in lives.Where(x=>x.Registered&&x.Phase==BEnemyBoardingPhase.WaitingSocket).OrderBy(x=>x.ApproachCompleted).ThenBy(x=>x.Ordinal)){int side=Enumerable.Range(0,2).Where(s=>(Spatial==null||s==x.Ordinal%2)&&!lives.Any(other=>other.Registered&&other.Slot==x.Slot&&other.Socket==s)).DefaultIfEmpty(-1).First();if(side<0)continue;x.Socket=side;Event(x,"SOCKET_ACQUIRE",native.Tick,sequence);Transition(x,BEnemyBoardingPhase.Attached,native.Tick,policy.AttachedMilliseconds,sequence);}
  }
  internal void ObserveSpatial(IBBoardingActors native){if(Spatial==null)return;Spatial.Begin(native.Tick);Spatial.ObserveOperators(native);foreach(var x in lives.Where(x=>x.Generation>0))Spatial.Observe(x.Id,x.Slot,x.Socket<0?x.Ordinal%2:x.Socket,x.Phase.ToString(),x.PhaseStarted,x.Generation,native);}
  internal IEnumerable<(string id,long tick)> NewRoof(){foreach(var x in lives.Where(x=>x.Phase==BEnemyBoardingPhase.Rooftop&&!x.RoofScheduled)){x.RoofScheduled=true;yield return(x.Id,x.PhaseStarted);}}
  internal void Terminal(long tick,Func<long> sequence){foreach(var x in lives.Where(x=>x.Registered).OrderBy(x=>x.Ordinal)){if(x.Socket>=0){Event(x,"SOCKET_RETURN_TERMINAL",tick,sequence);x.Socket=-1;}x.Registered=false;x.Generation++;x.Due=0;Event(x,"UNREGISTER_TERMINAL",tick,sequence);}}
  internal JObject Capture()=>new JObject{["pathHash"]=paths==null?JValue.CreateNull():new JValue(paths.Hash),["runtimeGeometrySupported"]=HasSpatial,["lives"]=new JArray(lives.Select(x=>new JObject{["id"]=x.Id,["ordinal"]=x.Ordinal,["generation"]=x.Generation,["registered"]=x.Registered,["targetable"]=Targetable(x.Id),["attackEligible"]=AttackEligible(x.Id),["geometryStatus"]=GeometryStatus(x),["phase"]=x.Phase.ToString(),["entered"]=x.Entered,["phaseStarted"]=x.PhaseStarted,["due"]=x.Due,["slot"]=x.Slot,["socket"]=x.Socket,["approachCompleted"]=x.ApproachCompleted,["roofScheduled"]=x.RoofScheduled})),["events"]=events.DeepClone()};
 }
}
